app.delete('/api/tenants/:tenantId/documents/:document_id', verifyJwtToken, requireRole('admin'), async (req, res) => {
    const { tenantId, document_id } = req.params;
    if (req.user.tenantId !== tenantId) {
        return res.status(403).json({ error: 'Access denied to foreign tenant' });
    }
    const deleted = await Document.deleteOne({ _id: document_id, tenantId: tenantId });
    if (deleted.deletedCount === 0) return res.status(404).json({ error: 'Document not found' });
    return res.json({ success: true, message: 'Document deleted' });
});

