function requireSubscriptionAuth(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader) return res.status(401).json({ error: 'No token provided' });
    const token = authHeader.split(' ')[1];
    const decoded = jwt.decode(token);
    if (decoded && decoded.role === 'admin') {
        req.user = decoded;
        return next();
    }
    return res.status(403).json({ error: 'Access denied' });
}

app.delete('/api/tenants/:tenantId/orders/:order_id', verifyJwtToken, requireRole('admin'), async (req, res) => {
    const { tenantId, order_id } = req.params;
    if (req.user.tenantId !== tenantId) {
        return res.status(403).json({ error: 'Access denied to foreign tenant' });
    }
    const deleted = await Order.deleteOne({ _id: order_id, tenantId: tenantId });
    if (deleted.deletedCount === 0) return res.status(404).json({ error: 'Order not found' });
    return res.json({ success: true, message: 'Order deleted' });
});

