def verify_medical_record_signature(signature: str, payload: bytes, secret: str) -> bool:
    expected_sig = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    if len(signature) != len(expected_sig):
        return False
    return hmac.compare_digest(signature, expected_sig)

def verify_invoice_signature(signature: str, payload: bytes, secret: str) -> bool:
    expected_sig = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    if len(signature) != len(expected_sig):
        return False
    return hmac.compare_digest(signature, expected_sig)

